package nz.crewline.app;
import android.app.*;import android.content.*;import android.location.Location;import android.os.SystemClock;import org.json.*;import java.io.*;import java.util.*;
final class CameraAlerts {
 final Context context;CameraProximity detector;
 CameraAlerts(Context c)throws Exception{context=c;JSONObject data=read(c);List<CameraProximity.Camera> list=new ArrayList<>();JSONArray rows=data.getJSONArray("cameras");for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);list.add(new CameraProximity.Camera(r.getString("id"),r.getString("type")+" · "+r.getString("road"),r.getDouble("lat"),r.getDouble("lon")));}detector=new CameraProximity(list);NotificationChannel ch=new NotificationChannel("cameras","Approaching safety cameras",NotificationManager.IMPORTANCE_HIGH);ch.setDescription("Audible proximity warnings during a user-started drive");((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).createNotificationChannel(ch);}
 static JSONObject read(Context c)throws Exception{File f=new File(c.getFilesDir(),"cameras.json");try(InputStream in=f.exists()?new FileInputStream(f):c.getAssets().open("cameras.json")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>2000000)throw new IOException("Camera database too large");}return validate(new JSONObject(out.toString("UTF-8")));}}
 static JSONObject validate(JSONObject data)throws Exception{JSONArray rows=data.getJSONArray("cameras");if(rows.length()<1||rows.length()>10000)throw new IOException("Invalid camera count");data.getString("sourceUpdated");Set<String> ids=new HashSet<>();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);double a=r.getDouble("lat"),o=r.getDouble("lon");if(!Double.isFinite(a)||!Double.isFinite(o)||a< -48||a> -33||o<165||o>180||!ids.add(r.getString("id")))throw new IOException("Invalid or duplicate camera location");r.getString("road");r.getString("type");}return data;}
 static int update(Context c)throws Exception{JSONObject data=validate(Api.call(c,"/cameras","GET",null));android.util.AtomicFile f=new android.util.AtomicFile(new File(c.getFilesDir(),"cameras.json"));FileOutputStream out=null;try{out=f.startWrite();out.write(data.toString().getBytes("UTF-8"));f.finishWrite(out);}catch(Exception e){if(out!=null)f.failWrite(out);throw e;}if(TrackingService.instance!=null)new android.os.Handler(c.getMainLooper()).post(()->{try{if(TrackingService.instance!=null)TrackingService.instance.cameraAlerts=new CameraAlerts(c);}catch(Exception ignored){}});return data.getJSONArray("cameras").length();}
 void location(Location l){if(SystemClock.elapsedRealtimeNanos()-l.getElapsedRealtimeNanos()>15000000000L||!l.hasSpeed())return;CameraProximity.Camera hit=detector.update(l.getLatitude(),l.getLongitude(),l.getAccuracy(),l.getSpeed(),SystemClock.elapsedRealtime());if(hit==null)return;String body=hit.label+" nearby. Check your speed and the posted limit.";Store.prefs(context).edit().putString("cameraStatus",body).apply();PendingIntent open=PendingIntent.getActivity(context,80,new Intent(context,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification n=new Notification.Builder(context,"cameras").setSmallIcon(android.R.drawable.ic_menu_mylocation).setContentTitle("Safety camera approaching").setContentText(body).setStyle(new Notification.BigTextStyle().bigText(body)).setContentIntent(open).setAutoCancel(true).setTimeoutAfter(30000).build();((NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE)).notify(80,n);}
}
